mapper.select:
		/*	설  명 : 과목별과제목록조회 */
		SELECT MAIN.*
            , ROWNUM AS RNUM
            , CASE
                /* 제출기간 미설정 */
                WHEN MAIN.ASMT_SBMSN_SDTTM IS NULL OR MAIN.ASMT_SBMSN_EDTTM IS NULL THEN '미설정'
                /* 일반 제출 진행중 */
                WHEN SYSDATE BETWEEN TO_DATE(MAIN.ASMT_SBMSN_SDTTM, 'YYYYMMDDHH24MISS')
                                    AND TO_DATE(MAIN.ASMT_SBMSN_EDTTM, 'YYYYMMDDHH24MISS') THEN '진행'

                /* 연장 제출 진행중 */
                WHEN MAIN.EXTD_SBMSN_SDTTM IS NOT NULL
                 AND MAIN.EXTD_SBMSN_EDTTM IS NOT NULL
                 AND SYSDATE BETWEEN TO_DATE(MAIN.EXTD_SBMSN_SDTTM, 'YYYYMMDDHH24MISS')
                        AND TO_DATE(MAIN.EXTD_SBMSN_EDTTM, 'YYYYMMDDHH24MISS')THEN '진행'

                /* 제출 시작 전 */
                WHEN SYSDATE < TO_DATE(MAIN.ASMT_SBMSN_SDTTM, 'YYYYMMDDHH24MISS') THEN '대기'

                /* 연장 제출 시작 전 */
                WHEN MAIN.EXTD_SBMSN_SDTTM IS NOT NULL
                 AND SYSDATE < TO_DATE(MAIN.EXTD_SBMSN_SDTTM, 'YYYYMMDDHH24MISS')
                 AND SYSDATE > TO_DATE(MAIN.ASMT_SBMSN_EDTTM, 'YYYYMMDDHH24MISS') THEN '대기'

                /* 모든 기간 종료 */
                ELSE '종료'
            END AS ASMT_PRGRS_STS
        FROM (

        ) MAIN
		WHERE MAIN.SBJCT_ID = #{sbjctId}

