/*
    SQL ID : AsmtDAO.asmtModify
    설  명 : 과제 수정
*/
UPDATE TB_LMS_ASMT
SET
      ASMT_TTL               = #{asmtTtl}
    , LCTR_WKNO_SCHDL_ID     = #{lctrWknoSchdlId}
    , ASMT_CTS               = #{asmtCts}
    , ASMT_GBNCD             = #{asmtGbncd}
    , SBASMT_TYCD            = #{sbasmtTycd}
    , EVL_SCR_TYCD           = #{evlScrTycd}
    , RUBRIC_ID              = CASE WHEN #{evlScrTycd} = 'RUBRIC_SCR' THEN #{rubricId} ELSE NULL END
    , SBMSN_FILE_MIME_TYCD   = #{sbmsnFileMimeTycd}

    , EXLN_ASMT_DWLDYN       = #{exlnAsmtDwldyn}


    , TMBR_INDIV_SBMSN_PRMYN = #{tmbrIndivSbmsnPrmyn}

    , MRK_RFLTYN             = #{mrkRfltyn}
    , MRK_OYN                = #{mrkOyn}
    , MRK_INQ_SDTTM          = FN_DTTM_FORMAT(#{mrkInqSdttm})
    , MRK_INQ_EDTTM          = FN_DTTM_FORMAT(#{mrkInqEdttm})
    , SBASMT_OSTD_OYN        = #{sbasmtOstdOyn}
    , SBASMT_OSTD_OPEN_EDTTM = FN_DTTM_FORMAT(#{sbasmtOstdOpenEdttm})
    , SBASMT_OSTD_OPEN_SDTTM = FN_DTTM_FORMAT(#{sbasmtOstdOpenSdttm})

    , RESBMSN_SDTTM          = FN_DTTM_FORMAT(#{resbmsnSdttm})


    , RESBMSN_EDTTM          = FN_DTTM_FORMAT(#{resbmsnEdttm})


    , RESBMSN_MRK_RFLTRT     = #{resbmsnMrkRfltrt}

    , ASMT_SBMSN_SDTTM       = FN_DTTM_FORMAT(#{asmtSbmsnSdttm})
    , ASMT_SBMSN_EDTTM       = FN_DTTM_FORMAT(#{asmtSbmsnEdttm})
    , EXTD_SBMSN_PRMYN       = #{extdSbmsnPrmyn}
    , EXTD_SBMSN_SDTTM       = FN_DTTM_FORMAT(#{extdSbmsnSdttm})
    , EXTD_SBMSN_EDTTM       = FN_DTTM_FORMAT(#{extdSbmsnEdttm})
    , EXTD_SBMSN_MRK_RFLTRT  = #{extdSbmsnMrkRfltrt}

    , TEAM_GRP_ID             = #{teamGrpId}


    , BYTEAM_ASMT_USEYN      = #{byteamAsmtUseyn}

    , MDFR_ID                = #{mdfrId}
    , MOD_DTTM               = FN_DTTM()
WHERE ASMT_ID = #{asmtId}

/*
    SQL ID : AsmtDAO.subAsmtModify
    설  명 : 부과제 수정
*/
UPDATE TB_LMS_ASMT
SET
      ASMT_TTL  = #{asmtTtl}
    , ASMT_CTS  = #{asmtCts}
    , DVCLAS_NO = #{dvclasNo}
    , MDFR_ID   = #{mdfrId}
    , MOD_DTTM  = FN_DTTM()
WHERE ASMT_ID = #{asmtId}

/* SQL ID : AsmtDAO.asmtEvlScrBulkModify 설 명 : 과제 평가 점수 일괄 수정 */ MERGE INTO TB_LMS_ASMT_EVL ASMT_EVL USING ( SELECT USR.* , CASE WHEN USR.SCORE_TYPE = 'addition' THEN USR.SCR ELSE ROUND( USR.SCR * CASE WHEN NVL(SBMSN.SBMSN_STSCD, USR.SBMSN_STSCD) = 'EXTD_SBMSN_CMPTN' THEN NVL(ASMT.EXTD_SBMSN_MRK_RFLTRT, 100) WHEN NVL(SBMSN.SBMSN_STSCD, USR.SBMSN_STSCD) = 'RESBMSN_CMPTN' THEN NVL(ASMT.RESBMSN_MRK_RFLTRT, 100) ELSE 100 END / 100 , 2 ) END AS RFLT_SCR FROM (
SELECT #{item.asmtEvlId} AS ASMT_EVL_ID , #{item.asmtId} AS ASMT_ID , #{item.asmtSbmsnId} AS ASMT_SBMSN_ID , #{item.sbmsnStscd} AS SBMSN_STSCD , #{item.userId} AS USER_ID , #{item.teamId} AS TEAM_ID , TO_NUMBER(#{item.scr}) AS SCR , #{item.scoreType} AS SCORE_TYPE , #{item.rgtrId} AS RGTR_ID , #{item.mdfrId} AS MDFR_ID FROM DUAL
) USR LEFT JOIN TB_LMS_ASMT_SBMSN SBMSN ON SBMSN.ASMT_SBMSN_ID = USR.ASMT_SBMSN_ID AND SBMSN.DELYN = 'N' LEFT JOIN TB_LMS_ASMT ASMT ON ASMT.ASMT_ID = USR.ASMT_ID ) USR ON ( ASMT_EVL.ASMT_ID = USR.ASMT_ID AND ASMT_EVL.USER_ID = USR.USER_ID ) WHEN MATCHED THEN UPDATE SET ASMT_EVL.ASMT_SBMSN_ID = USR.ASMT_SBMSN_ID , ASMT_EVL.SCR = CASE WHEN USR.SCORE_TYPE = 'addition' THEN CASE WHEN NVL(ASMT_EVL.SCR, 0) + USR.SCR < 0 THEN 0 WHEN NVL(ASMT_EVL.SCR, 0) + USR.SCR > 100 THEN 100 ELSE NVL(ASMT_EVL.SCR, 0) + USR.SCR END ELSE CASE WHEN USR.RFLT_SCR < 0 THEN 0 WHEN USR.RFLT_SCR > 100 THEN 100 ELSE USR.RFLT_SCR END END , ASMT_EVL.EVLYN = 'Y' , ASMT_EVL.MDFR_ID = USR.MDFR_ID , ASMT_EVL.MOD_DTTM = FN_DTTM() WHEN NOT MATCHED THEN INSERT ( ASMT_EVL_ID , ASMT_SBMSN_ID , SCR , EVLYN , RGTR_ID , REG_DTTM , ASMT_ID , USER_ID , TEAM_ID ) VALUES ( USR.ASMT_EVL_ID , USR.ASMT_SBMSN_ID , CASE WHEN USR.RFLT_SCR < 0 THEN 0 WHEN USR.RFLT_SCR > 100 THEN 100 ELSE USR.RFLT_SCR END , 'Y' , USR.RGTR_ID , FN_DTTM() , USR.ASMT_ID , USR.USER_ID , USR.TEAM_ID )

