mapper.select:
/* SQL ID : AsmtDAO.teamTrgtList 설 명 : 팀 대상 목록 조회 */ SELECT TEAM.TEAM_ID , MBR.USER_ID FROM TB_LMS_TEAM TEAM JOIN TB_LMS_TEAM_MBR MBR ON MBR.TEAM_ID = TEAM.TEAM_ID WHERE TEAM.TEAM_GRP_ID = #{teamGrpId} AND TEAM.TEAM_CPST_CMPTNYN = 'Y'
AND TEAM.TEAM_ID = #{teamId}
ORDER BY TEAM.TEAMNM

/* SQL ID : AsmtDAO.asmtCopyList 설 명 : 이전과제 가져오기 과제 목록 */ SELECT ASMT.ASMT_ID , ASMT.ASMT_TTL , ASMT.ASMT_GBNCD , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE LANG_CD = NVL(#{langCd}, 'ko') AND UP_CD = 'ASMT_GBNCD' AND CD = ASMT.ASMT_GBNCD) AS ASMT_GBNNM , SBJCT.SBJCT_ID , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , ROW_NUMBER() OVER(ORDER BY ASMT.ASMT_SBMSN_SDTTM) AS LINE_NO FROM TB_LMS_SBJCT_ADM SBJCT_ADM JOIN TB_LMS_ASMT ASMT ON SBJCT_ADM.SBJCT_ID = ASMT.SBJCT_ID AND ASMT.DELYN = 'N' AND ASMT.UP_ASMT_ID IS NULL JOIN TB_LMS_SBJCT SBJCT ON SBJCT.SBJCT_ID = ASMT.SBJCT_ID WHERE SBJCT_ADM.USER_ID = #{userId} AND SBJCT_ADM.SBJCT_ADM_TYCD = 'PROF'
AND SBJCT.SMSTR_CHRT_ID = #{smstrChrtId}
AND SBJCT.SBJCT_ID = #{sbjctId}
AND ASMT.ASMT_TTL LIKE FN_LIKE_VAL(#{searchValue})

mapper.sql:
SELECT ASMT.ASMT_ID /* 일반과제: 메인 과제 ID / 부과제: 부과제 ID */ , ASMT.UP_ASMT_ID /* 일반과제: NULL / 부과제: 상위과제 ID */ , ASMT.SBJCT_ID , ASMT.ASMT_PRCTCYN , ASMT.SBASMT_TYCD , ASMT.SBMSN_FILE_MIME_TYCD , ASMT.INDV_ASMTYN , ASMT.TEAM_ASMT_STNGYN , ASMT.BYTEAM_ASMT_USEYN , ASMT.TMBR_INDIV_SBMSN_PRMYN , ASMT.ASMT_GBNCD , ASMT.RUBRIC_ID , ASMT.EXTD_SBMSN_PRMYN , ASMT.EXTD_SBMSN_EDTTM , TRGT.USER_ID , USR.USERNM , USR.STDNT_NO , DEPT.DEPTNM , TRGT.TEAM_ID , TEAM.TEAMNM , MBR.LDRYN , MBR.ROLE , TRGT.RESBMSN_PRMYN /* 제출 */ , USER_SBMSN.ASMT_SBMSN_ID , USER_SBMSN.SBMSN_DTTM , USER_SBMSN.SBMSN_TYCD , USER_SBMSN.SBMSN_TXT , USER_SBMSN.FILE_CNT /* 제출상태 */ , CASE WHEN USER_SBMSN.ASMT_SBMSN_ID IS NOT NULL THEN USER_SBMSN.SBMSN_STSCD WHEN NVL(TRGT.RESBMSN_PRMYN, 'N') = 'Y' THEN 'NON_RESBMSN' WHEN NVL(ASMT.EXTD_SBMSN_PRMYN, 'N') = 'Y' AND ASMT.EXTD_SBMSN_EDTTM IS NOT NULL AND FN_DTTM() > ASMT.ASMT_SBMSN_EDTTM AND ( ASMT.EXTD_SBMSN_SDTTM IS NULL OR FN_DTTM() >= ASMT.EXTD_SBMSN_SDTTM ) THEN 'EXTD_NON_SBMSN' ELSE 'NON_SBMSN' END AS SBMSN_STSCD /* 평가 */ , EVL.ASMT_EVL_ID , EVL.SCR , NVL(EVL.EVLYN, 'N') AS EVLYN , EVL.EVL_MEMO , EVL.EXLN_ASMTYN , EVL.MAX_MOSART /* 피드백 */ , NVL(FDBK.FDBK_CNT, 0) AS FDBK_CNT FROM ( /* * 하위 부과제가 있으면 하위 부과제만 조회 */ SELECT SUB_ASMT.ASMT_ID FROM TB_LMS_ASMT SUB_ASMT WHERE SUB_ASMT.UP_ASMT_ID = #{asmtId} AND SUB_ASMT.DELYN = 'N'
UNION ALL
/* * 하위 부과제가 없으면 상위과제 조회 */ SELECT ASMT.ASMT_ID FROM TB_LMS_ASMT ASMT WHERE ASMT.ASMT_ID = #{asmtId} AND ASMT.DELYN = 'N' AND NOT EXISTS ( SELECT 1 FROM TB_LMS_ASMT SUB_ASMT WHERE SUB_ASMT.UP_ASMT_ID = ASMT.ASMT_ID AND SUB_ASMT.DELYN = 'N' ) ) TARGET_ASMT JOIN TB_LMS_ASMT ASMT ON ASMT.ASMT_ID = TARGET_ASMT.ASMT_ID /* 대상 : USER 기준, TEAM_ID는 참고용 */ JOIN TB_LMS_ASMT_SBMSN_TRGT TRGT ON TRGT.ASMT_ID = ASMT.ASMT_ID /* 수강상태 확인 */ JOIN TB_LMS_ATNDLC ATNDLC ON ATNDLC.SBJCT_ID = ASMT.SBJCT_ID AND ATNDLC.USER_ID = TRGT.USER_ID AND ATNDLC.AUDITYN = 'N' AND ATNDLC.ATNDLC_STSCD = 'APPROVE' JOIN TB_LMS_USER USR ON USR.USER_ID = TRGT.USER_ID LEFT JOIN TB_LMS_DEPT DEPT ON DEPT.DEPT_ID = USR.DEPT_ID /* 팀 : 표시용 */ LEFT JOIN TB_LMS_TEAM TEAM ON TEAM.TEAM_ID = TRGT.TEAM_ID LEFT JOIN TB_LMS_TEAM_MBR MBR ON MBR.TEAM_ID = TRGT.TEAM_ID AND MBR.USER_ID = TRGT.USER_ID /* 마지막 제출 */ LEFT JOIN ( SELECT SBMSN.ASMT_ID , SBMSN.USER_ID , SBMSN.ASMT_SBMSN_ID , SBMSN.SBMSN_DTTM , SBMSN.SBMSN_TYCD , SBMSN.SBMSN_TXT , SBMSN.SBMSN_STSCD , FN_REF_FILE_CNT(SBMSN.ASMT_SBMSN_ID) AS FILE_CNT , ROW_NUMBER() OVER( PARTITION BY SBMSN.ASMT_ID , SBMSN.USER_ID ORDER BY SBMSN.SBMSN_DTTM DESC , SBMSN.REG_DTTM DESC , SBMSN.ASMT_SBMSN_ID DESC ) RN FROM TB_LMS_ASMT_SBMSN SBMSN WHERE SBMSN.DELYN = 'N' ) USER_SBMSN /* 팀과제(팀원별 제출 불가)는 제출 저장 시 팀원별 제출 row/파일이 복사되므로 USER_ID 기준 최신 제출을 사용한다. */ ON USER_SBMSN.ASMT_ID = ASMT.ASMT_ID AND USER_SBMSN.USER_ID = TRGT.USER_ID AND USER_SBMSN.RN = 1 /* 평가 */ LEFT JOIN TB_LMS_ASMT_EVL EVL ON EVL.ASMT_ID = ASMT.ASMT_ID AND EVL.USER_ID = TRGT.USER_ID /* 피드백 */ LEFT JOIN ( SELECT FDBK.ASMT_ID , FDBK.USER_ID , COUNT(*) AS FDBK_CNT FROM TB_LMS_ASMT_FDBK FDBK WHERE FDBK.DELYN = 'N' GROUP BY FDBK.ASMT_ID , FDBK.USER_ID ) FDBK ON FDBK.ASMT_ID = ASMT.ASMT_ID AND FDBK.USER_ID = TRGT.USER_ID

mapper.select:
/* SQL ID : AsmtDAO.asmtEvlList 설 명 : 과제 평가 목록 */ SELECT MAIN.* , CD.CDNM AS SBMSN_STSNM FROM ( SELECT ROW_NUMBER() OVER( ORDER BY NVL(BASE.TEAMNM, 'ZZZ') , NVL(BASE.LDRYN, 'N') DESC
, BASE.STDNT_NO , BASE.USERNM
, CASE WHEN BASE.ASMT_SBMSN_ID IS NOT NULL THEN 0 ELSE 1 END , BASE.SBMSN_DTTM DESC , BASE.USERNM
, BASE.USERNM , BASE.STDNT_NO
) AS LINE_NO , COUNT(1) OVER() AS TOTAL_CNT , BASE.* FROM (
) BASE WHERE 1 = 1
AND BASE.LDRYN = 'Y'
AND BASE.LDRYN = 'N'
AND BASE.SBMSN_STSCD = #{sbmsnStscd}
AND BASE.EVLYN = #{evlYn}
AND BASE.TEAM_ID = #{teamId}
AND ( LOWER(BASE.DEPTNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(BASE.STDNT_NO) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(BASE.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
) MAIN LEFT JOIN TB_LMS_CMMN_CD CD ON CD.LANG_CD = NVL(#{langCd}, 'ko') AND CD.UP_CD = 'SBMSN_STSCD' AND CD.CD = MAIN.SBMSN_STSCD ORDER BY NVL(MAIN.TEAMNM, 'ZZZ') , NVL(MAIN.LDRYN, 'N') DESC
, MAIN.STDNT_NO , MAIN.USERNM
, CASE WHEN MAIN.ASMT_SBMSN_ID IS NOT NULL THEN 0 ELSE 1 END , MAIN.SBMSN_DTTM DESC , MAIN.USERNM
, MAIN.USERNM , MAIN.STDNT_NO

/*
    SQL ID : AsmtDAO.asmtEvlSelect
    설  명 : 과제 평가 조회(단건)
*/
SELECT BASE.*
FROM (

) BASE
WHERE BASE.ASMT_ID = #{asmtId}
    AND BASE.USER_ID = #{userId}

/* SQL ID : AsmtDAO.stdntAsmtListPaging 설 명 : 학생 과제 목록 페이징 */
SELECT MAIN.* , ROW_NUMBER() OVER(ORDER BY MAIN.ASMT_SBMSN_SDTTM, MAIN.ASMT_ID) AS LINE_NO , COUNT(*) OVER() AS TOTAL_CNT FROM ( SELECT BASE.* , CD.CDNM AS SBMSN_STSNM FROM ( SELECT ASMT.* , TRGT.TARGET_ASMT_ID , TRGT.ASMT_SBMSN_TRGT_ID , TRGT.USER_ID , TRGT.TEAM_ID , TRGT.RESBMSN_PRMYN , SBMSN.ASMT_SBMSN_ID , SBMSN.SBMSN_DTTM , CASE WHEN ASMT.ASMT_SBMSN_SDTTM IS NULL OR ASMT.ASMT_SBMSN_EDTTM IS NULL THEN 'BEFORE' WHEN FN_DTTM() < ASMT.ASMT_SBMSN_SDTTM THEN 'BEFORE' WHEN FN_DTTM() BETWEEN ASMT.ASMT_SBMSN_SDTTM AND ASMT.ASMT_SBMSN_EDTTM THEN 'PROGRESS' WHEN NVL(ASMT.EXTD_SBMSN_PRMYN, 'N') = 'Y' AND ASMT.EXTD_SBMSN_EDTTM IS NOT NULL AND FN_DTTM() > ASMT.ASMT_SBMSN_EDTTM AND FN_DTTM() <= ASMT.EXTD_SBMSN_EDTTM AND ( ASMT.EXTD_SBMSN_SDTTM IS NULL OR FN_DTTM() >= ASMT.EXTD_SBMSN_SDTTM ) THEN 'EXT_PROGRESS' ELSE 'CLOSED' END AS ASMT_PRGRS_STS , CASE WHEN SBMSN.ASMT_SBMSN_ID IS NOT NULL THEN SBMSN.SBMSN_STSCD WHEN NVL(TRGT.RESBMSN_PRMYN, 'N') = 'Y' THEN 'NON_RESBMSN' WHEN NVL(ASMT.EXTD_SBMSN_PRMYN, 'N') = 'Y' AND ASMT.EXTD_SBMSN_EDTTM IS NOT NULL AND FN_DTTM() > ASMT.ASMT_SBMSN_EDTTM AND ( ASMT.EXTD_SBMSN_SDTTM IS NULL OR FN_DTTM() >= ASMT.EXTD_SBMSN_SDTTM ) THEN 'EXTD_NON_SBMSN' ELSE 'NON_SBMSN' END AS SBMSN_STSCD , EVL.ASMT_EVL_ID , EVL.SCR , NVL(EVL.EVLYN, 'N') AS EVLYN , NVL(FDBK.FDBK_CNT, 0) AS FDBK_CNT FROM (
) ASMT JOIN ( SELECT NVL(TRGT_ASMT.UP_ASMT_ID, TRGT_ASMT.ASMT_ID) AS ROOT_ASMT_ID , TRGT_ASMT.ASMT_ID AS TARGET_ASMT_ID , TRGT.ASMT_SBMSN_TRGT_ID , TRGT.USER_ID , TRGT.TEAM_ID , TRGT.RESBMSN_PRMYN , ROW_NUMBER() OVER( PARTITION BY NVL(TRGT_ASMT.UP_ASMT_ID, TRGT_ASMT.ASMT_ID), TRGT.USER_ID ORDER BY CASE WHEN TRGT_ASMT.UP_ASMT_ID IS NULL THEN 1 ELSE 0 END , TRGT_ASMT.ASMT_ID ) AS RN FROM TB_LMS_ASMT_SBMSN_TRGT TRGT JOIN TB_LMS_ASMT TRGT_ASMT ON TRGT_ASMT.ASMT_ID = TRGT.ASMT_ID AND TRGT_ASMT.SBJCT_ID = #{sbjctId} AND TRGT_ASMT.DELYN = 'N' JOIN TB_LMS_ATNDLC ATNDLC ON ATNDLC.SBJCT_ID = TRGT_ASMT.SBJCT_ID AND ATNDLC.USER_ID = TRGT.USER_ID AND ATNDLC.AUDITYN = 'N' AND ATNDLC.ATNDLC_STSCD = 'APPROVE' WHERE TRGT.USER_ID = #{userId} ) TRGT ON TRGT.ROOT_ASMT_ID = ASMT.ASMT_ID AND TRGT.RN = 1 LEFT JOIN ( SELECT SBMSN.ASMT_ID , SBMSN.USER_ID , SBMSN.ASMT_SBMSN_ID , SBMSN.SBMSN_DTTM , SBMSN.SBMSN_STSCD , ROW_NUMBER() OVER( PARTITION BY SBMSN.ASMT_ID, SBMSN.USER_ID ORDER BY SBMSN.SBMSN_DTTM DESC , SBMSN.REG_DTTM DESC , SBMSN.ASMT_SBMSN_ID DESC ) AS RN FROM TB_LMS_ASMT_SBMSN SBMSN WHERE SBMSN.DELYN = 'N' ) SBMSN ON SBMSN.ASMT_ID = TRGT.TARGET_ASMT_ID AND SBMSN.USER_ID = TRGT.USER_ID AND SBMSN.RN = 1 LEFT JOIN TB_LMS_ASMT_EVL EVL ON EVL.ASMT_ID = TRGT.TARGET_ASMT_ID AND EVL.USER_ID = TRGT.USER_ID LEFT JOIN ( SELECT FDBK.ASMT_ID , FDBK.USER_ID , COUNT(*) AS FDBK_CNT FROM TB_LMS_ASMT_FDBK FDBK WHERE FDBK.DELYN = 'N' GROUP BY FDBK.ASMT_ID , FDBK.USER_ID ) FDBK ON FDBK.ASMT_ID = TRGT.TARGET_ASMT_ID AND FDBK.USER_ID = TRGT.USER_ID WHERE ASMT.SBJCT_ID = #{sbjctId} AND ASMT.DELYN = 'N' AND ASMT.UP_ASMT_ID IS NULL AND ASMT.ASMT_OYN = 'Y'
AND LOWER(ASMT.ASMT_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
) BASE LEFT JOIN TB_LMS_CMMN_CD CD ON CD.LANG_CD = NVL(#{langCd}, 'ko') AND CD.UP_CD = 'SBMSN_STSCD' AND CD.CD = BASE.SBMSN_STSCD ) MAIN

mapper.insert:
/*
    SQL ID : AsmtDAO.stdntAsmtSbmsnRegist
    설  명 : 학생 과제 제출 등록
*/
INSERT INTO TB_LMS_ASMT_SBMSN (
      ASMT_SBMSN_ID
    , ASMT_ID
    , USER_ID
    , TEAM_ID
    , SBMSN_DTTM
    , SBMSN_TYCD
    , SBMSN_CTS
    , SBMSN_TXT
    , SBMSN_STSCD
    , SBMSN_CNT
    , CNTN_IP
    , DELYN
    , RGTR_ID
    , REG_DTTM
) VALUES (
      #{asmtSbmsnId}
    , #{asmtId}
    , #{userId}
    , #{teamId}
    , FN_DTTM()
    , #{sbmsnTycd}
    , #{sbmsnCts}
    , #{sbmsnTxt}
    , #{sbmsnStscd}
    , (
        SELECT
              NVL(MAX(SBMSN.SBMSN_CNT), 0) + 1
        FROM TB_LMS_ASMT_SBMSN SBMSN
        WHERE SBMSN.ASMT_ID = #{asmtId}
            AND SBMSN.USER_ID = #{userId}
            AND SBMSN.DELYN = 'N'
      )
    , #{cntnIp}
    , 'N'
    , #{rgtrId}
    , FN_DTTM()
)

mapper.update:
/*
    SQL ID : AsmtDAO.stdntAsmtSbmsnModify
    설  명 : 학생 과제 제출 수정
*/
UPDATE TB_LMS_ASMT_SBMSN
SET
      SBMSN_DTTM = FN_DTTM()
    , SBMSN_TYCD = #{sbmsnTycd}
    , SBMSN_CTS = #{sbmsnCts}
    , SBMSN_TXT = #{sbmsnTxt}
    , SBMSN_STSCD = #{sbmsnStscd}
    , SBMSN_CNT = NVL(SBMSN_CNT, 0) + 1
    , CNTN_IP = #{cntnIp}
    , MDFR_ID = #{mdfrId}
    , MOD_DTTM = FN_DTTM()
WHERE ASMT_SBMSN_ID = #{asmtSbmsnId}
    AND ASMT_ID = #{asmtId}
    AND USER_ID = #{userId}
    AND DELYN = 'N'

mapper.select:
/* SQL ID : AsmtDAO.stdntExlnAsmtList 설 명 : 학생 우수과제 목록 조회 */ WITH REQ_ASMT AS ( SELECT NVL(ASMT.UP_ASMT_ID, ASMT.ASMT_ID) AS ROOT_ASMT_ID , ASMT.SBJCT_ID FROM TB_LMS_ASMT ASMT WHERE ASMT.ASMT_ID = #{asmtId} AND ASMT.DELYN = 'N' ) , TARGET_ASMT AS ( SELECT SUB_ASMT.ASMT_ID FROM REQ_ASMT REQ JOIN TB_LMS_ASMT SUB_ASMT ON SUB_ASMT.UP_ASMT_ID = REQ.ROOT_ASMT_ID AND SUB_ASMT.DELYN = 'N'
UNION ALL
SELECT ROOT_ASMT.ASMT_ID FROM REQ_ASMT REQ JOIN TB_LMS_ASMT ROOT_ASMT ON ROOT_ASMT.ASMT_ID = REQ.ROOT_ASMT_ID AND ROOT_ASMT.DELYN = 'N' WHERE NOT EXISTS ( SELECT 1 FROM TB_LMS_ASMT SUB_ASMT WHERE SUB_ASMT.UP_ASMT_ID = ROOT_ASMT.ASMT_ID AND SUB_ASMT.DELYN = 'N' ) ) SELECT EVL.ASMT_ID , ASMT.ASMT_TTL , EVL.ASMT_EVL_ID , EVL.ASMT_SBMSN_ID , EVL.USER_ID , EVL.TEAM_ID , USR.USERNM , USR.STDNT_NO , TEAM.TEAMNM , MBR.LDRYN , EVL.SCR , NVL(EVL.EVLYN, 'N') AS EVLYN , SBMSN.SBMSN_DTTM , SBMSN.SBMSN_TXT , CASE WHEN SBMSN.SBMSN_TXT IS NULL THEN NULL WHEN LENGTH(SBMSN.SBMSN_TXT) > 30 THEN SUBSTR(SBMSN.SBMSN_TXT, 1, 30) || '...' ELSE SBMSN.SBMSN_TXT END AS SBMSN_TXT_SUMMARY , FN_REF_FILE_CNT(EVL.ASMT_SBMSN_ID) AS FILE_CNT , ROW_NUMBER() OVER( ORDER BY NVL(TEAM.TEAMNM, 'ZZZ') , NVL(MBR.LDRYN, 'N') DESC , USR.USERNM , SBMSN.SBMSN_DTTM DESC , EVL.MOD_DTTM DESC , EVL.ASMT_EVL_ID DESC ) AS LINE_NO FROM TARGET_ASMT TARGET JOIN TB_LMS_ASMT ASMT ON ASMT.ASMT_ID = TARGET.ASMT_ID JOIN TB_LMS_ASMT_EVL EVL ON EVL.ASMT_ID = TARGET.ASMT_ID AND EVL.EXLN_ASMTYN = 'Y' JOIN TB_LMS_USER USR ON USR.USER_ID = EVL.USER_ID LEFT JOIN TB_LMS_TEAM TEAM ON TEAM.TEAM_ID = EVL.TEAM_ID LEFT JOIN TB_LMS_TEAM_MBR MBR ON MBR.TEAM_ID = EVL.TEAM_ID AND MBR.USER_ID = EVL.USER_ID LEFT JOIN TB_LMS_ASMT_SBMSN SBMSN ON SBMSN.ASMT_SBMSN_ID = EVL.ASMT_SBMSN_ID AND SBMSN.DELYN = 'N' ORDER BY NVL(TEAM.TEAMNM, 'ZZZ') , NVL(MBR.LDRYN, 'N') DESC , USR.USERNM , SBMSN.SBMSN_DTTM DESC , EVL.MOD_DTTM DESC , EVL.ASMT_EVL_ID DESC
